module circuit (
    input a, b, c,
    output out
);
    wire w0, w1, w2, w3, w4, w5, w6, w7;

    not n0(c, w0);
    not n1(b, w1);

    and a0(w0, w1, w2);
    not n2(a, w3);

    and a1(w3, a, w4);
    and a2(w2, b, w5);

    or o0(w4, w5, w6);

    and a3(w0, c, w7);
    or o1(w6, w7, out);
endmodule

