module custom_shift_register(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);
    wire clk;
    wire D;
    wire clear;
    wire Q;

    assign clk = rst;
    assign clear = load;

    for (genvar i = 0; i < 8; i = i + 1) begin : shift_register
        assign D = (i == 0) ? (pin[7] & pin[6] & pin[5] & pin[4] & pin[3] & pin[2] & pin[1] & pin[0]) : (pin[i-1]);
