module top_module (
  input clk,
  input shift_ena,
  input count_ena,
  input data,
  output reg [3:0] q
);
  wire Q0, Q1, Q2, Q3;

  // inputs to gate
  wire n_val_0, n_val_2, n_val_1_2ored, n_val_0_1_2, n_val_3, n_val_0_3ored;

  assign n_val_0 = ~clk;
  assign n_val_2 = ~count_ena;
  assign n_val_1_2ored = shift_ena & count_ena;
  assign n_val_0_1_2 = clk | n_val_1_2ored;
  assign n_val_3 = ~data;
  assign n_val_0_3ored = clk | n_val_3;

  // first DFF (Q0)
  reg Q0_reg;
  always @ (posedge clk) begin
    if (n_val_3) Q0_reg = n_val_0 | n_val_1_2ored;
    else Q0_reg = n_val_0_3ored;
  end
  assign Q0 = Q0_reg;

  // second DFF (Q1)
  reg Q1_reg;
  always @ (posedge shift_ena) begin
    if (n_val_2) Q1_reg = 1'b1;
    else Q1_reg = clk & shift_ena;
  end
  assign Q1 = Q1_reg;

  // third DFF (Q2)
  reg Q2_reg;
  always @ (posedge count_ena) begin
    if (count_ena) Q2_reg = shift_ena & count_ena;
    else Q2_reg = n_val_0 & n_val_2;
  end
  assign Q2 = Q2_reg;

  // fourth DFF (Q3)
  reg Q3_reg;
  always @ (posedge data) begin
    if (data) Q3_reg = 1'b0;
    else Q3_reg = clk & count_ena;
  end
  assign Q3 = Q3_reg;

  always @(*) begin
    q = {Q3, Q2, Q1, Q0};
  end

endmodule

