      q_temp2 = reg_val;
    end else begin
      q_temp3 = reg_val;
    end
    reg_val = reg_c;
  end

  always @(C, D, Q) begin
    if (C & D) begin
      Q = reg_val;
    end
  end

  initial begin
    out = 4'b0000;
  end

  always @(*) begin
    out = clk & rst;
  end
