module testbench(

    input  clk, 
    input  rst_n,
    input  data_in, 
    output sequence_detected				
);

reg sequence_detected;
reg Q, S, T;
reg per0, pre1, pre2;
reg per0_log, pre1_log, pre2_log;

always @(clk or rst_n or data_in or Q) begin
	if (!(per0_log&pre0) & (per0_log | pre0)) begin
		per0 = 1'b0;
		pre0 = 1'b0;
	end
	else if (per0_log & pre0) begin
		per0 = 1'b1;
		pre0 = 1'b1;
	end
	else if ((per0_log & pre0) & !(per0_log | pre0)) begin
		per0 = 1'b1;
		pre0 = 1'b0;
	end
end
always @ (clk or rst_n or data_in) begin
	Q = 0;
	if (clk) begin
		Q |= 1;
		if (rst_n) begin
			Q |= 1;
		end
		else if (data_in) begin
			Q |= 1;
		end
	end
	per0_log = 1'b0;
	pre0_log = 1'b0;
	per0 = ~(per0 & clk) & (Q or clk);
	per0_log = ~(per0 & clk) & (Q or clk);
end
always delay @ (per0, pre0, per0_log, pre0_log, Q, clk, rst_n, data_in) begin
	S = 1'b0;
	T = 1'b0;
	per0_log = pre0;
	pre0_log = per0;
end
always @(T, S) begin
	T = 1'b0;
	if (S) begin
		// explicit truth table based on illustration
		T = Q & pre0 | per0 & Q | per0 & pre0;
		// something wrong with the code interpretation on the flip-flop input side
		S = S & pre0 & per0 | Q & pre0 & per0 | per0 & Q & pre0;
		sequence_detected = sequence_detected & pre0 & per0 | Q & pre0 & per0 | per0 & Q & pre0;
	end
	else if (per0 & (Q & pre0 | pre0 & Q)) begin
		T = ~(Q & pre0) | pre0 & Q;
	end
end
just_use_this_for_verification = 0;
sequence_detected = T;
endmodule

