module top_module(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected
     );

    wire s_diff_pn0_c, s_diff_pn0_r, s_diff_pn0_d, s_diff_pn0_q, s_diff_pn0_ql, s_diff_pn0_qr, s_diff_pn1_c, s_diff_pn1_r, s_diff_pn1_d, s_diff_pn1_q, s_diff_pn1_ql, s_diff_pn1_qr, cl, sl;

    assign s_diff_pn0_c = clk & rst_n;
    assign s_diff_pn1_d = s_diff_pn0_c & data_in;

    assign s_diff_pn0_r = ~s_diff_pn0_q & clk;
    assign s_diff_pn0_ql = s_diff_pn0_r & rst_n;
    assign s_diff_pn0_qr = s_diff_pn0_ql & data_in;

    assign s_diff_pn1_c = s_diff_pn0_ql;
    assign s_diff_pn1_r = ~s_diff_pn1_q & clk;
    assign s_diff_pn1_ql = s_diff_pn1_r & rst_n;
    assign s_diff_pn1_qr = s_diff_pn1_ql & data_in;

    assign s_diff_pn0_d = s_diff_pn1_ql & s_diff_pn0_c;
