module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
reg s_dff_pn0_q, s_dff_pn1_q, s_dff_pn0_q0, s_dff_pn0_q1, s_dff_pn1_q0;
reg [3:0] s_dff_pn0_q3;
reg [3:0] s_dff_pn1_q3;

always @(*) begin
    s_dff_pn0_q = rst_n & ~data_in;
end

always @(*) begin
    s_dff_pn1_q = ~s_dff_pn0_q1 & clk;
end

always @(*) begin
    s_dff_pn0_q0 = s_dff_pn1_q & s_dff_pn0_q | s_dff_pn0_q;
end

always @(*) begin
    s_dff_pn0_q1 = s_dff_pn0_q0 & ~s_dff_pn0_q;
end

always @(*) begin
    s_dff_pn1_q0 = s_dff_pn1_q & s_dff_pn0_q1 | s_dff_pn1_q0;
end

always @(*) begin
    s_dff_pn0_q3 = s_dff_pn0_q | s_dff_pn0_q1 & s_dff_pn0_q0;
end

always @(*) begin
    s_dff_pn1_q3 = s_dff_pn1_q & s_dff_pn0_q1 | s_dff_pn1_q0;
end

assign sequence_detected = s_dff_pn1_q3 & s_dff_pn0_q1 | s_dff_pn1_q0 & s_dff_pn0_q1;

endmodule
